import javax.swing.*;import java.awt.*;import java.util.*;
public class App{
 record Puzzle(String title,String[]ranks,String move,String explanation){}
 static final Puzzle[]PUZZLES={new Puzzle("White to move — queen check",new String[]{"....k...","........","........","........","........","........","...Q....","....K..."},"d2e2","The queen reaches e2 and checks the king on e8 along the file."),new Puzzle("White to move — knight check",new String[]{"....k...","........","........","...N....","........","........","........","....K..."},"d5f6","A knight on f6 attacks e8. Knights jump over intervening pieces."),new Puzzle("White to move — rook check",new String[]{"....k...","........","........","........","........","........","R.......","....K..."},"a2a8","The rook moves to a8 and checks the king along rank eight.")};
 static boolean answer(Puzzle p,String move){return move.replace(" ","").toLowerCase(Locale.ROOT).equals(p.move);}
 public static void main(String[]args){if(args.length>0&&args[0].equals("--self-test")){for(Puzzle p:PUZZLES){if(p.ranks.length!=8||Arrays.stream(p.ranks).anyMatch(r->r.length()!=8)||!answer(p,p.move.toUpperCase(Locale.ROOT))||answer(p,"bad"))throw new AssertionError();}System.out.println("Board shape and answer normalization passed");return;}SwingUtilities.invokeLater(()->{JFrame f=new JFrame("Chess Tactics Trainer");f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setSize(680,800);JPanel root=new JPanel(new BorderLayout(12,12));root.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));f.setContentPane(root);JLabel title=new JLabel();root.add(title,BorderLayout.NORTH);JPanel board=new JPanel(new GridLayout(8,8));root.add(board,BorderLayout.CENTER);JPanel bottom=new JPanel(new BorderLayout());root.add(bottom,BorderLayout.SOUTH);JTextField move=new JTextField();move.setToolTipText("Coordinate move: e2e7");bottom.add(move,BorderLayout.NORTH);JTextArea feedback=new JTextArea(4,30);feedback.setLineWrap(true);feedback.setWrapStyleWord(true);feedback.setEditable(false);bottom.add(feedback,BorderLayout.CENTER);JPanel buttons=new JPanel();bottom.add(buttons,BorderLayout.SOUTH);int[]index={0},score={0};Set<Integer>solved=new HashSet<>();Map<Character,String>symbols=Map.of('K',"♔",'Q',"♕",'R',"♖",'N',"♘",'k',"♚");Runnable draw=()->{board.removeAll();Puzzle p=PUZZLES[index[0]];title.setText(p.title+" · solved "+score[0]+"/"+PUZZLES.length);for(int r=0;r<8;r++)for(int c=0;c<8;c++){JLabel cell=new JLabel(symbols.getOrDefault(p.ranks[r].charAt(c),""),SwingConstants.CENTER);cell.setFont(new Font("Serif",Font.PLAIN,40));cell.setOpaque(true);cell.setBackground((r+c)%2==0?new Color(231,224,199):new Color(117,150,117));cell.setToolTipText(""+(char)('a'+c)+(8-r));board.add(cell);}board.revalidate();board.repaint();move.setText("");};JButton submit=new JButton("Check coordinate move"),hint=new JButton("Show answer"),next=new JButton("Next puzzle");buttons.add(submit);buttons.add(hint);buttons.add(next);submit.addActionListener(e->{Puzzle p=PUZZLES[index[0]];if(answer(p,move.getText())){if(solved.add(index[0]))score[0]++;feedback.setText("Correct. "+p.explanation);title.setText(p.title+" · solved "+score[0]+"/"+PUZZLES.length);}else feedback.setText("Try another move. Use origin+destination, such as e2e7.");});hint.addActionListener(e->feedback.setText(PUZZLES[index[0]].move+": "+PUZZLES[index[0]].explanation));next.addActionListener(e->{index[0]=(index[0]+1)%PUZZLES.length;feedback.setText("");draw.run();});draw.run();f.setLocationRelativeTo(null);f.setVisible(true);});}
}
